// Map assets shared by the admin pin picker (Task 24) and the food map (Task 26).
// The styles are generated by scripts/map-styles.mjs (OpenFreeMap vector tiles).

/** The light MapLibre style, served from public/map/. */
export const MAP_STYLE_LIGHT = "/map/style-light.json";
/** The dark twin: same sources and layer ids, darker paint. */
export const MAP_STYLE_DARK = "/map/style-dark.json";

export const mapStyleFor = (theme: "light" | "dark") => (theme === "dark" ? MAP_STYLE_DARK : MAP_STYLE_LIGHT);

/** The food map's opening frame (spec §6.5): San Francisco to Berkeley, the Peninsula to Marin. [west, south, east, north]. */
export const BAY_AREA_BOUNDS: [number, number, number, number] = [-122.56, 37.68, -122.16, 37.95];

/**
 * The tiles' required credit (OpenFreeMap's TileJSON wording). Also given to
 * the attribution control directly, so it shows even when the tiles don't
 * load; MapLibre drops the duplicate when they do.
 */
export const MAP_ATTRIBUTION =
  '<a href="https://openfreemap.org" target="_blank">OpenFreeMap</a> <a href="https://www.openmaptiles.org/" target="_blank">&copy; OpenMapTiles</a> Data from <a href="https://www.openstreetmap.org/copyright" target="_blank">OpenStreetMap</a>';
